Here is the commit message:
pty: fix O_CLOEXEC for TIOCGPTPEER

It was being ignored because the flags were not passed to fd allocation.

Fixes: 54ebbfb16034 ("tty: add TIOCGPTPEER ioctl")
Signed-off-by: Matthijs van Duin <matthijsvanduin@gmail.com>
Acked-by: Aleksa Sarai <asarai@suse.de>
Cc: stable <stable@vger.kernel.org>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by the O_CLOEXEC flag being ignored during the file descriptor allocation because the `get_unused_fd_flags` function was called with a hardcoded value of `0` instead of the appropriate `flags` parameter. This prevented the intended behavior of the file descriptor from being set correctly when using the TIOCGPTPEER ioctl.

Here is the patch:
  */
 int ptm_open_peer(struct file *master, struct tty_struct *tty, int flags)
 {
 	int fd = -1;
 	struct file *filp;
 	int retval = -EINVAL;
 	struct path path;

 	if (tty->driver != ptm_driver)
 		return -EIO;

-	fd = get_unused_fd_flags(0);
+	fd = get_unused_fd_flags(flags);
 	if (fd < 0) {
 		retval = fd;
 		goto err;
 	}

 	/* Compute the slave's path */
 	path.mnt = devpts_mntget(master, tty->driver_data);
 	if (IS_ERR(path.mnt)) {
 		retval = PTR_ERR(path.mnt);
 		goto err_put;
 	}
 	path.dentry = tty->link->driver_data;

 	filp = dentry_open(&path, flags, current_cred());
 	mntput(path.mnt);
 	if (IS_ERR(filp)) {
 		retval = PTR_ERR(filp);
 		goto err_put;
 	}

 	fd_install(fd, filp);
 	return fd;

 err_put:
 	put_unused_fd(fd);
 err:
 	return retval;
 }



